#!/bin/bash
# Stamp the current time into BuildStamp.swift so a running server can report
# which binary it is. Runs as a pre-build phase for both targets.
#
# Why this exists: serverVersion is bumped by hand and therefore gets forgotten,
# so two different builds can report the same version. When that happens there is
# no way to tell "my change isn't deployed" from "my change is deployed and
# didn't work" — which has already burned debugging time on this project.
set -euo pipefail

OUT="${SRCROOT:-$(cd "$(dirname "$0")/.." && pwd)}/iCTRLKit/BuildStamp.swift"
STAMP="$(date '+%Y-%m-%d %H:%M')"

# Only rewrite when the minute actually changed — an unconditional write makes
# every build dirty the file and recompile everything that imports it.
if [ -f "$OUT" ] && grep -q "\"$STAMP\"" "$OUT" 2>/dev/null; then
  exit 0
fi

cat > "$OUT" <<EOF
// GENERATED by Scripts/stamp-build.sh — do not edit.
enum BuildStamp {
    static let value = "$STAMP"
}
EOF
echo "🕒 build stamp: $STAMP"
